begin;
do $review$
declare item jsonb;p public.hb_policy_versions%rowtype;s public.hb_policy_sources%rowtype;new_rules jsonb;
 reviewed timestamptz := '2026-10-11T16:46:36Z';
begin
 for item in select value from jsonb_array_elements($plans$[{"slug":"attestation-of-commercial-invoices-via-edas-2-0","source":"https://www.mofa.gov.ae/services/edas-attestation-v2","authority":"mofa","fields":["fees","duration"],"fees":"150 درهماً لكل فاتورة أو شهادة منشأ.","duration":"دقيقتان وفق بطاقة الخدمة.","feesEn":"AED 150 per invoice or certificate of origin.","durationEn":"Two minutes according to the service card.","nameAr":"تصديق فاتورة تجارية أو شهادة منشأ عبر eDAS 2.0","nameEn":"Attestation of commercial invoices via eDAS 2.0 with MOFA","sourceReviewedAt":"2026-10-08","evidenceBranch":"agent/official-missing-detail-evidence","evidenceCapturedAt":"2026-10-08T16:49:47.056Z"},{"slug":"equivalency-of-general-education-certificate-from-abroad-grade-12","source":"https://moe.gov.ae/en/eservices/servicecard/Pages/CertEquivalent-Out.aspx","authority":"moe","fields":["fees","duration"],"fees":"50 درهماً.","duration":"من 3 إلى 30 يوم عمل بحسب اكتمال الشروط والحاجة إلى المراسلات أو مراجعة اللجنة؛ لا تحتسب فترة النواقص ضمن مدة الإنجاز.","feesEn":"AED 50.","durationEn":"3–30 working days depending on complete requirements, correspondence and committee review. Time spent resolving missing documents is excluded.","nameAr":"معادلة شهادة الثانوية من خارج الإمارات","nameEn":"Equivalency of a general education certificate from abroad Grade 12 with the UAE Ministry of Education","sourceReviewedAt":"2026-10-08","evidenceBranch":"agent/official-missing-detail-evidence","evidenceCapturedAt":"2026-10-08T16:49:47.056Z"},{"slug":"equivalency-of-general-education-certificate-in-the-uae-grade-12","source":"https://moe.gov.ae/en/eservices/servicecard/pages/certequivalent.aspx","authority":"moe","fields":["fees","duration"],"fees":"50 درهماً.","duration":"5 أيام عمل وفق بطاقة الخدمة.","feesEn":"AED 50.","durationEn":"5 working days according to the service card.","nameAr":"معادلة شهادة ثانوية منهاج أجنبي داخل الإمارات","nameEn":"Equivalency of a general education certificate in the UAE Grade 12 with the UAE Ministry of Education","sourceReviewedAt":"2026-10-08","evidenceBranch":"agent/official-missing-detail-evidence","evidenceCapturedAt":"2026-10-08T16:49:47.056Z"},{"slug":"confirming-the-authenticity-of-equivalency","source":"https://moe.gov.ae/ar/eservices/servicecard/pages/certificateequilizationverification.aspx","authority":"moe","fields":["fees","duration"],"fees":"مجانية.","duration":"فورية بعد إدخال البيانات الصحيحة.","feesEn":"Free of charge.","durationEn":"Immediate after entering the correct details.","nameAr":"التحقق من صحة المعادلة أو التصديق","nameEn":"Confirming the authenticity of an equivalency certificate with the UAE Ministry of Education","sourceReviewedAt":"2026-10-08","evidenceBranch":"agent/official-missing-detail-evidence","evidenceCapturedAt":"2026-10-08T16:49:47.056Z"}]$plans$::jsonb) loop
  begin
   select * into strict p from public.hb_policy_versions where policy_key='service:'||(item->>'slug') and status='active' for update;
   select * into strict s from public.hb_policy_sources where id=any(p.source_ids) and source_url=item->>'source' and authority_key=(item->>'authority') and active for update;
  exception when no_data_found then raise notice 'Scoped reviewed MOE/eDAS grounding records absent in clean seed: %',item->>'slug';continue;end;
  select coalesce(jsonb_agg(value order by ordinality),'[]'::jsonb) into new_rules from jsonb_array_elements(p.rules) with ordinality where coalesce(value->>'id','') not in ('fees','duration');
  new_rules:=new_rules||jsonb_build_array(
   jsonb_build_object('id','fees','when','[]'::jsonb,'effect','review','reason',item->>'fees','actions',jsonb_build_array('review_fees'),'sourceRefs',jsonb_build_array(item->>'source')),
   jsonb_build_object('id','duration','when','[]'::jsonb,'effect','review','reason',item->>'duration','actions',jsonb_build_array('review_duration'),'sourceRefs',jsonb_build_array(item->>'source')));
  if p.reviewed_by='reviewed-moe-edas-policy-field-sync-2026-10-11' and p.rules=new_rules then continue;end if;
  update public.hb_policy_versions set status='retired',effective_until=reviewed where id=p.id;
  insert into public.hb_policy_versions(policy_key,jurisdiction_id,version,effective_from,status,rules,source_ids,reviewed_by,reviewed_at,country_pack_id)
  values(p.policy_key,p.jurisdiction_id,p.version+1,reviewed,'active',new_rules,p.source_ids,'reviewed-moe-edas-policy-field-sync-2026-10-11',reviewed,p.country_pack_id);
  update public.hb_policy_sources set metadata=metadata||jsonb_build_object('fee_time_grounding_checkpoint','reviewed-moe-edas-policy-field-sync-2026-10-11','fee_time_grounding_synced_at',reviewed,'fee_time_source_reviewed_at',item->>'sourceReviewedAt','fee_time_evidence_branch',item->>'evidenceBranch','fee_time_verification_scope','Reuse accepted 2026-10-08 reviewed fees and duration only; no new source verification or health reclassification') where id=s.id;
 end loop;
end $review$;
commit;
